// A small, valid MiniC program: functions, loops and arithmetic.
int factorial(int n) {
  int result = 1;
  while (n > 1) {
    result = result * n;
    n = n - 1;
  }
  return result;
}

int main() {
  int x = factorial(5);
  return x;
}

// The declaration of `total` is missing its ';'.
int main() {
  int total = 0
  int i = 1;
  while (i <= 10) {
    total = total + i;
    i = i + 1;
  }
  return total;
}

// The if-condition is missing its closing ')'.
int clamp(int value, int limit) {
  if (value > limit {
    value = limit;
  }
  return value;
}

// The while loop is missing its opening '{' (the indentation shows intent).
int sum(int n) {
  int i = 0;
  int s = 0;
  while (i < n)
    s = s + i;
    i = i + 1;
  }
  return s;
}

// A binary operator is missing its right operand.
int area(int w, int h) {
  int a = w * ;
  return a;
}

// Two independent errors: a missing ';' and a missing ')'.
int score(int a, int b) {
  int s = a + b
  if (s > 100 {
    s = 100;
  }
  return s;
}

// Which operator was intended between `a` and `b`? Many repairs parse.
int combine(int a, int b) {
  int c = a b;
  return c;
}

// The variable name is missing. Any repair must invent a name,
// so IntelliFix should not claim a confident correction.
int main() {
  int = 42;
  return 0;
}

// Valid program with nested blocks, arrays, for-loops and logic.
int grid[16];

int count_even(int a[], int n) {
  int count = 0;
  for (int i = 0; i < n; i = i + 1) {
    if (a[i] % 2 == 0 && a[i] != 0) {
      count = count + 1;
    } else {
      if (!(a[i] < 0)) {
        continue;
      }
    }
  }
  return count;
}

int main() {
  for (int i = 0; i < 16; i = i + 1) {
    grid[i] = i * (i - 3);
  }
  return count_even(grid, 16);
}

// A stray '@' is not a MiniC character.
int main() {
  int x = 5 @ 3;
  return x;
}

// `i++` is valid C but MiniC deliberately omits ++/--.
int main() {
  int i = 0;
  i++;
  return i;
}

// A duplicated ')' after a call.
int twice(int x) {
  return x * 2;
}

int main() {
  int y = twice(4));
  return y;
}
